import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print("No combination found")
        return

    n = int(data[0])
    target = int(data[1])

    if n == 0:
        print("No combination found")
        return

    arr = list(map(int, data[2:2+n]))
    arr.sort()

    result = []

    def backtrack(start, path, current_sum):
        if current_sum == target:
            result.append(path[:])
            return
        if current_sum > target:
            return

        for i in range(start, n):
            num = arr[i]
            if num > 0 and current_sum + num > target:
                break
            path.append(num)
            backtrack(i, path, current_sum + num)
            path.pop()

    backtrack(0, [], 0)

    if not result:
        print("No combination found")
    else:
        for combo in result:
            print(' '.join(map(str, combo)))

if __name__ == "__main__":
    main()
